else if(sty==='electric'){ crust=[230,25,12]; crust2=[235,20,18]; lavaH=195; }
else if(sty==='amethyst'){ crust=[275,25,13]; crust2=[280,20,19]; lavaH=290; }
else if(sty==='gold'){ crust=[35,30,14]; crust2=[38,25,20]; lavaH=45; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }
function proj(fx,fz){ const zz=0.15+fz*3.0; const sy=hor+(H-hor)*(1/(1+zz*0.9)); const sx=W*0.5+fx*W*0.7*(1/(1+zz*0.5)); return [sx,sy]; }
// crust ground base (below horizon only)
let g=dc.createLinearGradient(0,hor,0,H); g.addColorStop(0,Cc(crust2,100).toString()); g.addColorStop(1,Cc(crust,100).toString());
