  for(let k=0;k<=nseg;k++){ const fx=(k/nseg-0.5)*2; const jig=(fr(zi*31+k)-0.5)*0.16 + Math.sin(t*0.2+zi+k)*0.008; pts.push(proj(fx, fz + jig*0.4)); }
  const br=pulse(fz);
  const wgt=(1.2+ (1-fz)*4*P.glow);
  stroke(color(lavaH, lavaS, 100, (30+br*55)*P.alpha/100)); strokeWeight(wgt*(0.7+br*0.5)); noFill();
  beginShape(); for(const p2 of pts) vertex(p2[0],p2[1]); endShape();
  stroke(color(lavaH, lavaS*0.5, 100, (12+br*22)*P.alpha/100)); strokeWeight(wgt*2.4);
  beginShape(); for(const p2 of pts) vertex(p2[0],p2[1]); endShape();
  // vertical connector cracks
  if(zi<NZ-1 && P.cracks>0.2){ for(let k=0;k<3;k++){ const fx=(fr(zi*7+k)-0.5)*1.8; const [x1,y1]=proj(fx,fz); const [x2,y2]=proj(fx+(fr(zi+k)-0.5)*0.2, fz+1/NZ);
    const b2=pulse(fz+0.05); stroke(color(lavaH,lavaS,100,(22+b2*40)*P.alpha/100)); strokeWeight(wgt*0.7); line(x1,y1,x2,y2); } }
}
dc.restore(); blendMode(BLEND); noStroke();
// dark plate highlights (subtle top light)
