// embers rising from cracks
if(P.emberR>0.05){ dc.save(); blendMode(ADD); for(let i=0;i<P.emberR*30;i++){ const life=(t*(0.25+en*0.25)+fr(i))%1; const fz=fr(i+3); const [ex,ey]=proj((fr(i)-0.5)*1.8, fz); fill(color(lavaH,lavaS,100,(1-life)*60*P.alpha/100)); circle(ex+Math.sin(t*2+i)*10, ey-life*120*(1-fz*0.5), (2.2)*(1-fz*0.5)); } dc.restore(); blendMode(BLEND); }
